// src/MapDisplay.js
import React from 'react';
import './App.css';
import 'leaflet/dist/leaflet.css';
import { MapContainer, TileLayer, Marker, Popup, Polyline } from 'react-leaflet';
import L from 'leaflet';

function MapDisplay({ routeData, defaultCenter, zoom }) {
  return (
    <MapContainer
      center={[10.776345751453743, 106.7011806321713]} // center of Ho Chi Minh City
      zoom={11.5}
      style={{ height: '400px', width: '100%' }}
      dragging={true}
      scrollWheelZoom={true}
      doubleClickZoom={true}
      zoomControl={true}
    >
      <TileLayer
        attribution='&copy; <a href="https://openstreetmap.org">OpenStreetMap</a> contributors'
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
      />

      {routeData && routeData.map((coord, idx) => {
        const numberIcon = L.divIcon({
          className: '', // no extra wrapper styling
          html: `<div class="number-marker">${idx + 1}</div>`,
          iconSize:    [28, 28],
          iconAnchor:  [14, 28],  // bottom-center of the marker
          popupAnchor: [0, -30]
        });

        return (
          <Marker
            key={idx}
            position={coord}
            icon={numberIcon}
          >
            <Popup>
              Stop {idx + 1}:<br/>
              [{coord[0].toFixed(5)}, {coord[1].toFixed(5)}]
            </Popup>
          </Marker>
        );
      })}

      {routeData && routeData.length > 1 && (
        <Polyline positions={routeData} weight={4} color="blue" />
      )}
    </MapContainer>
  );
}

export default MapDisplay;
